import logging
import re

from ute_ue.config import loggers as ta_ue_logging
from ute_ue.utils.proxy_mngr import ProxiedCfgFileBasedUePool

from .at_ue import AtUe
from .exceptions import AutomaticallyComPortIdentificationFailed, UeReservationFailure
from .quectel_ue import QuectelUe
from .smawave_ue import SmawaveUE
from .sequans_ue import SequansUe

# TODO: What about moving it to versioning.py
# variables used to deploy proxy service via proxy mngr
MIN_REQUIRED_UEPROXY_VER = "1.16.0"
MIN_REQUIRED_ACCESS_VER = "1.1.0"


class TafUeAtPool(ProxiedCfgFileBasedUePool):
    """UePool for At UEs"""

    def __init__(self, config_file_path=None, inline_config=None):
        """
        Constructor

        :param config_file_path: path to config.yml
        :param inline_config: dict containing information included under 'inline_config' key in config.yml
        """
        self.inline_config = inline_config

        super().__init__(config_file_path, inline_config)

        self.rpc_clients = set()
        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {"area": "UEPOOL"})

    def create_device(self, device_name, *args):
        """
        Create instance of UE class

        :param device_name: UE name from config.yml
        :return: AtUe object
        """
        device_config = self.inline_config[device_name]["CONSTRUCTOR_PARAMETERS"]
        configuration = device_config["configuration"]
        self.prepare_ueproxy_service(self.inline_config[device_name])
        class_name = self.inline_config[device_name].get("CLASS", "")
        device_config["access"] = re.sub(r"^(ue)|(ue)$", "", class_name.lower())
        if class_name and class_name.lower() != "at":
            device_config["sub_access"] = class_name
        rpc_client = self.get_ueproxy_connection_client_by(configuration["ue_pc_address"])
        self.rpc_clients.add(rpc_client)
        self.logger.debug(f"executing create_device with name {device_name} and configuration {device_config}")
        prefix = "COM"
        if class_name == "Quectel":
            device_config = self.update__ue_config__if__com_port__is_not_provided(device_config, rpc_client)
            prefix = self._update__quectel_com_port_prefix__linux(device_config)
            ue_name = f"Quectel_{device_config['com_port']}"
            at_ue = QuectelUe(name=device_name,
                              ue_config=device_config,
                              ue_pc=rpc_client,
                              prefix=prefix)
        elif class_name == 'Smawave':
            prefix = "sma"
            ue_name = "Smawave"
            at_ue = SmawaveUE(name=device_name, ue_config=device_config, ue_pc=rpc_client, prefix=prefix)
        elif class_name == 'Sequans':
            device_config = self.update__ue_config__if__com_port__is_not_provided(device_config, rpc_client)
            ue_name = f"Sequans_{device_config['com_port']}"
            at_ue = SequansUe(name=device_name,
                         ue_config=device_config,
                         ue_pc=rpc_client,
                         prefix=prefix)
        else:
            device_config = self.update__ue_config__if__com_port__is_not_provided(device_config, rpc_client)
            ue_name = f"COM{device_config['com_port']}"
            at_ue = AtUe(name=device_name,
                         ue_config=device_config,
                         ue_pc=rpc_client,
                         prefix=prefix)

        is_reservation_successful = at_ue.prepare_ue()
        if not is_reservation_successful:
            raise UeReservationFailure(f"UE {ue_name} reservation failed")
        return at_ue

    def update__ue_config__if__com_port__is_not_provided(self, ue_config, ue_pc):
        is_linux_com_port = "ttyusb" in str(ue_config.get("com_port", "")).lower()
        if "com_port" not in ue_config.keys() or ue_config["com_port"].lower() in ["dynamic", ""]:
            self.logger.debug("Trying to get connected UE com port from UE PC")
            ue_config["com_port"] = self._get_ue_com_port(ue_pc)
            return ue_config
        elif ue_config["com_port"].isdigit() or is_linux_com_port:
            return ue_config
        else:
            raise AutomaticallyComPortIdentificationFailed(
                'Wrong value for com_port in the config file. Please set com_port to "dynamic" or provide correct com_port'
            )

    @staticmethod
    def _update__quectel_com_port_prefix__linux(ue_config, prefix="COM") -> str:
        return "" if "ttyusb" in str(ue_config["com_port"]).lower() else prefix

    def _get_ue_com_port(self, ue_pc):
        available_ues = ue_pc.get_available_ues()["ue_ids"]
        if len(available_ues) == 1:
            com_port = available_ues[0][available_ues[0].index("M") + 1 :]
            self.logger.debug(f"Found UE with port COM{com_port}")
            return com_port
        elif len(available_ues) > 1:
            raise AutomaticallyComPortIdentificationFailed("Too many UEs detected. Please provide com_port in your config file.")
        else:
            raise AutomaticallyComPortIdentificationFailed(
                "Ue not found on UE PC. Please ensure that the UE is correctly connected or is not reserved"
            )

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        for rpc_client in self.rpc_clients:
            self.ueproxy_teardown(rpc_client)
